const truckStatusHistory = `-- name: TruckStatusHistory :many
SELECT status, previous_status, changed_at, changed_by_user_id, changed_by_label, reason
FROM status_history
WHERE entity_type = 'truck' AND entity_id = $1
ORDER BY changed_at DESC, id DESC
`

type TruckStatusHistoryRow struct {
	Status          string
	PreviousStatus  *string
	ChangedAt       time.Time
	ChangedByUserID *uuid.UUID
	ChangedByLabel  *string
	Reason          *string
}

// GET /v1/trucks/{id}: the whole history, newest first (append-only, a few rows per truck).
func (q *Queries) TruckStatusHistory(ctx context.Context, truckID uuid.UUID) ([]TruckStatusHistoryRow, error) {
	rows, err := q.db.Query(ctx, truckStatusHistory, truckID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TruckStatusHistoryRow{}
	for rows.Next() {
		var i TruckStatusHistoryRow
		if err := rows.Scan(
			&i.Status,
			&i.PreviousStatus,
			&i.ChangedAt,
			&i.ChangedByUserID,
			&i.ChangedByLabel,
			&i.Reason,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateTruck = `-- name: UpdateTruck :exec
UPDATE trucks
SET license_plate = $1, province = $2, vin = $3,
    engine_number = $4, gps_vehicle_id = $5, status = $6,
    legacy_status = CASE WHEN status IS DISTINCT FROM $6 THEN NULL ELSE legacy_status END,
    brand = $7, model = $8, year = $9, color = $10,
    type_raw = $11, vehicle_class = $12, seats = $13::smallint,
    fuel_type = $14, engine_capacity = $15::numeric,
    fuel_capacity = $16::numeric, max_load_weight_kg = $17::numeric,
    registration_date = $18::date, buying_date = $19::date,
    notes = $20, tax_expiry_date = $21::date,
    tax_expense_thb = $22::numeric, tax_responsible = $23,
    tax_renewal_status = $24, maintenance_responsible = $25,
    last_service_date = $26::date, next_service_date = $27::date,
    next_service_mileage = $28::int, pm_interval_km = $29::int,
    current_mileage = $30::int, insurance_policy_id = $31,
    insurance_policy_number = $32, insurance_company = $33,
    insurance_type = $34, insurance_start_date = $35::date,
    insurance_expiry_date = $36::date,
    insurance_premium_thb = $37::numeric, insurance_notes = $38,
    insurance_renewal_status = $39, payment_method = $40,
    updated_by = $41::uuid
WHERE id = $42
`

type UpdateTruckParams struct {
	LicensePlate           string
	Province               string
	Vin                    *string
	EngineNumber           *string
	GpsVehicleID           *string
	Status                 string
	Brand                  string
	Model                  string
	Year                   int16
	Color                  string
	TypeRaw                string
	VehicleClass           *string
	Seats                  *int16
	FuelType               *string
	EngineCapacity         *float64
	FuelCapacity           *float64
	MaxLoadWeightKg        *float64
	RegistrationDate       *time.Time
	BuyingDate             *time.Time
	Notes                  *string
	TaxExpiryDate          *time.Time
	TaxExpenseThb          *float64
	TaxResponsible         string
	TaxRenewalStatus       *string
	MaintenanceResponsible string
	LastServiceDate        *time.Time
	NextServiceDate        *time.Time
	NextServiceMileage     *int32
	PmIntervalKm           *int32
	CurrentMileage         *int32
	InsurancePolicyID      *string
	InsurancePolicyNumber  *string
	InsuranceCompany       *string
	InsuranceType          *string
	InsuranceStartDate     *time.Time
	InsuranceExpiryDate    *time.Time
	InsurancePremiumThb    *float64
	InsuranceNotes         *string
	InsuranceRenewalStatus *string
	PaymentMethod          *string
	Actor                  *uuid.UUID
	ID                     uuid.UUID
}

// PATCH, a renewal and an import update write the merged row (Go merges the request into the locked row);
// tenant_id and ownership_type never change here (tenant_id is frozen, trg_freeze_tenant_id). The maintenance columns
// last_alert_mileage and active_maintenance_id belong to the PM check and maintenance flows (P3), not to this write.
// legacy_status is the raw legacy value of the current status (Appendix A §A.2.2): a write that keeps the status
// keeps it, a status change clears it (the right-hand status is the old row's value).
func (q *Queries) UpdateTruck(ctx context.Context, arg UpdateTruckParams) error {
	_, err := q.db.Exec(ctx, updateTruck,
		arg.LicensePlate,
		arg.Province,
		arg.Vin,
		arg.EngineNumber,
		arg.GpsVehicleID,
		arg.Status,
		arg.Brand,
		arg.Model,
		arg.Year,
		arg.Color,
		arg.TypeRaw,
		arg.VehicleClass,
		arg.Seats,
		arg.FuelType,
		arg.EngineCapacity,
		arg.FuelCapacity,
		arg.MaxLoadWeightKg,
		arg.RegistrationDate,
		arg.BuyingDate,
		arg.Notes,
		arg.TaxExpiryDate,
		arg.TaxExpenseThb,
		arg.TaxResponsible,
		arg.TaxRenewalStatus,
		arg.MaintenanceResponsible,
		arg.LastServiceDate,
		arg.NextServiceDate,
		arg.NextServiceMileage,
		arg.PmIntervalKm,
		arg.CurrentMileage,
		arg.InsurancePolicyID,
		arg.InsurancePolicyNumber,
		arg.InsuranceCompany,
		arg.InsuranceType,
		arg.InsuranceStartDate,
		arg.InsuranceExpiryDate,
		arg.InsurancePremiumThb,
		arg.InsuranceNotes,
		arg.InsuranceRenewalStatus,
		arg.PaymentMethod,
		arg.Actor,
		arg.ID,
	)
	return err
}
